#!/bin/bash
# Task 133-w4-form2 -- meshsim sim/ WORKER4 (branch sim-w4 16b0ab8). TIMING TASK: keep the box quiet while it runs.
# Threads, form 2: one mesh over several threads (D18 clang release; the machine from sim/tools/machine.sh, D21):
#   0. build; test_threads and test_matrix (clang debug); the machine recorded (results/.../machine.txt);
#   1. the due mask's cost: one domain, due on against off, rates 0.35 and 0.05, one P core;
#   2. the split's own cost on one thread: 2, 4, 8 domains;
#   3. one mesh over 2, 4 and one-per-P-core threads against one: the barrier spinning, yielding after 200/2000/20000
#      pauses, and blocking; 3 repeats;
#   4. the barrier's own cost at rate 0;
#   5. VERDICT: one digest per rate over every run; 6. footprint, one domain against the splits.
# Expected ~5 min.
# From an embedded kit (sim/ at 16b0ab8: Makefile, src, bench/threads, the thread tests). Writes only results/133-w4-form2/.
# Scratch in /tmp, removed first and at the end. Safe to re-run.
set -u
cd "$(dirname "$0")/.."
REPO=$PWD; RES=$REPO/results/133-w4-form2; mkdir -p "$RES"; rm -f "$RES/raw.txt"
W=/tmp/w4-133-w4-form2; rm -rf "$W"; mkdir -p "$W"
sed -n '/^__KIT_BEGIN__$/,/^__KIT_END__$/p' "$0" | sed '1d;$d' | base64 -d > "$W/kit.tgz" || exit 2
GOT=$(sha256sum "$W/kit.tgz" | cut -d' ' -f1); echo "kit sha256 $GOT"
[ "$GOT" = "8d87c4f05f62d85a2520f5701af57a61ec439768b0d6c906110be23021664712" ] || { echo "kit sha256 mismatch (want 8d87c4f05f62d85a2520f5701af57a61ec439768b0d6c906110be23021664712)"; exit 2; }
mkdir -p "$W/kit" && tar -xzf "$W/kit.tgz" -C "$W/kit" || exit 2
S=$W/kit/sim
FAILS=0; FAIL=0
sec() { echo; echo "==== $*  [$(date +%T)]"; }
verdict() { echo "VERDICT $1: $2"; [ "$2" = PASS ] || FAIL=1; }
START=$(date +%s)
{
sec "machine (D21)"; . "$S/tools/machine.sh" "${QUEST_P_CPUS:-}" "${QUEST_E_CPUS:-}"; machine_record "$RES/machine.txt"; uptime
# Shared by W4's task bodies. run TAG CPUSET cmd...: one run under taskset (and perf stat when PERF=1); appends
# "TAG <bench line> [perf: ...]" to $RES/raw.txt.
run() {
  local tag=$1 cpus=$2; shift 2
  if [ "${PERF:-0}" = 1 ]; then
    taskset -c "$cpus" perf stat -x, -e cycles,instructions,cache-misses -o "$W/perf.csv" -- "$@" > "$W/out.txt" 2> "$W/err.txt"
  else
    taskset -c "$cpus" "$@" > "$W/out.txt" 2> "$W/err.txt"
  fi
  local rc=$?
  local line; line=$(grep -E '^threads ' "$W/out.txt" | tail -1)
  if [ $rc -ne 0 ] || [ -z "$line" ]; then echo "RUNFAIL $tag rc=$rc: $*"; head -5 "$W/err.txt"; FAILS=$((FAILS + 1)); return 1; fi
  local pc=""
  [ "${PERF:-0}" = 1 ] && pc=" perf: $(awk -F, '$3 ~ /cycles/ && $3 !~ /ref/ { split($3,a,"/"); k=(a[1]=="cpu_atom")?"atom":"core"; c[k]+=$1 }
      $3 ~ /instructions/ { split($3,a,"/"); k=(a[1]=="cpu_atom")?"atom":"core"; i[k]+=$1 }
      $3 ~ /cache-misses/ { split($3,a,"/"); k=(a[1]=="cpu_atom")?"atom":"core"; m[k]+=$1 }
      END { printf "core_cycles=%s core_instr=%s core_cmiss=%s atom_cycles=%s atom_instr=%s", c["core"], i["core"], m["core"], c["atom"], i["atom"] }' "$W/perf.csv")"
  echo "$tag $line$pc" | tee -a "$RES/raw.txt"
}
field() { grep -o "$1=[^ ]*" | cut -d= -f2; }
# Task body: form 2, one mesh over several threads (WORKER4). Sourced by the task (mk_task.sh); the machine from
# sim/tools/machine.sh (D21): P_ONE, P_CPUS, take, count.
cd "$S" || exit 2
sec "build (clang release, D18) and the thread tests (clang debug: ASan, UBSan)"
make -j8 CC_NAME=clang MODE=release build/clang-release/bench_threads > "$RES/build.log" 2>&1 || { tail -20 "$RES/build.log"; verdict build FAIL; exit 1; }
make -j8 CC_NAME=clang MODE=debug build/clang-debug/test_threads build/clang-debug/test_matrix >> "$RES/build.log" 2>&1 \
  && ./build/clang-debug/test_threads && ./build/clang-debug/test_matrix && verdict "test_threads, test_matrix (debug)" PASS \
  || verdict "test_threads, test_matrix (debug)" FAIL
B=build/clang-release/bench_threads
NP=$(count "$P_ONE"); P1=$(take 1 "$P_ONE")
MAXD=$(( NP < 8 ? NP : 8 ))                       # the mesh has 8 rows: at most 8 domains
V="--form 2 --cycles 60000 --warmup 2000"

sec "1. the due mask's cost: one domain, due on against off (as in a split machine's domains); rate 0.35 and 0.05; 3 repeats"
for rep in 1 2 3; do for r in 0.35 0.05; do
  run "due-on" "$P1" $B $V --rate $r --threads 1 --cpus "$P1"
  run "due-off" "$P1" $B $V --rate $r --threads 1 --cpus "$P1" --due-off
done; done

sec "2. the split's own cost on one thread: 2, 4 and $MAXD domains on CPU $P1; 3 repeats"
for rep in 1 2 3; do for d in 2 4 $MAXD; do
  run "split-1t-d$d" "$P1" $B $V --threads 1 --domains $d --cpus "$P1"
done; done

sec "3. one mesh over 2, 4 and $NP threads (one per P core) against one; the barrier: spin, yield after 200/2000/20000, block; 3 repeats"
for rep in 1 2 3; do
  run "one" "$P1" $B $V --threads 1 --cpus "$P1"
  for t in 2 4 $NP; do
    [ "$t" -gt "$MAXD" ] && continue
    C=$(take $t "$P_ONE")
    run "t$t-spin" "$P_CPUS" $B $V --threads $t --cpus "$C" --barrier spin
    for n in 200 2000 20000; do run "t$t-yield$n" "$P_CPUS" $B $V --threads $t --cpus "$C" --barrier yield --spins $n; done
    run "t$t-block" "$P_CPUS" $B $V --threads $t --cpus "$C" --barrier block
  done
done

sec "4. the barrier's own cost: rate 0 (routers step, no words move), 1 thread against $NP, spin and yield 2000; 3 repeats"
for rep in 1 2 3; do
  run "idle-one" "$P1" $B $V --rate 0 --threads 1 --cpus "$P1"
  run "idle-t$NP-spin" "$P_CPUS" $B $V --rate 0 --threads $NP --cpus "$(take $NP "$P_ONE")" --barrier spin
  run "idle-t$NP-yield" "$P_CPUS" $B $V --rate 0 --threads $NP --cpus "$(take $NP "$P_ONE")"
done

sec "5. digests: every run at a rate gives one digest (threads, domains, barrier, due mask)"
for r in 0.35 0.05 0.00; do
  n=$(grep "rate_in=$r " "$RES/raw.txt" | field digest | sort -u | wc -l)
  [ "$n" = 1 ] && verdict "digests at rate $r" PASS || verdict "digests at rate $r ($n distinct)" FAIL
done
sec "6. footprint: words, one domain against the splits"
grep -E "^(one|split-1t)" "$RES/raw.txt" | sed 's/.*domains=\([0-9]*\).*words=\([0-9]*\).*/domains \1 words \2/' | sort -u
[ "$FAILS" = 0 ] && verdict "every run completed" PASS || verdict "every run completed ($FAILS failed)" FAIL
sec "done in $(($(date +%s) - START)) s"
} 2>&1 | tee "$RES/run.log"
grep '^VERDICT' "$RES/run.log" > "$RES/VERDICTS.txt"
rm -rf "$W"
grep -q ': FAIL$' "$RES/VERDICTS.txt" && exit 1
exit 0
